// ── Groq AI Service — direct fast calls ──────────────────────
const GROQ_URL = 'https://api.groq.com/openai/v1/chat/completions';
const GROQ_KEY = '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';
const MODEL    = 'llama-3.3-70b-versatile';

async function groq(sys, usr, maxTokens = 1024, temp = 0.7) {
  const r = await fetch(GROQ_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${GROQ_KEY}` },
    body: JSON.stringify({
      model: MODEL, max_tokens: maxTokens, temperature: temp,
      messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }],
    }),
  });
  if (!r.ok) { const e = await r.json().catch(()=>{}); throw new Error(e?.error?.message || `Groq error ${r.status}`); }
  return (await r.json()).choices?.[0]?.message?.content?.trim() || '';
}

function parseJSON(raw) {
  let s = raw.replace(/```json|```/g, '').trim();
  const a = s.indexOf('['), o = s.indexOf('{');
  const start = a !== -1 && (o === -1 || a < o) ? a : o;
  if (start !== -1) {
    const open = s[start], close = open === '[' ? ']' : '}';
    let d = 0, end = -1;
    for (let i = start; i < s.length; i++) {
      if (s[i] === open) d++; if (s[i] === close && --d === 0) { end = i; break; }
    }
    if (end !== -1) s = s.slice(start, end + 1);
  }
  return JSON.parse(s.replace(/,\s*}/g,'}').replace(/,\s*]/g,']').replace(/[\u0000-\u001F]/g,' '));
}

// ── Generate questions for exam ───────────────────────────────
// Called by CreateExam — generates ALL questions in ONE call (fast)
export async function generateQuestions({ topic, difficulty, count, type }, onProgress) {
  const marks = difficulty === 'Easy' ? 5 : difficulty === 'Hard' ? 15 : 10;
  if (onProgress) onProgress(0, count);

  const optionsEx = type === 'MCQ'
    ? `,"options":[{"text":"correct answer","is_correct":true},{"text":"wrong 1","is_correct":false},{"text":"wrong 2","is_correct":false},{"text":"wrong 3","is_correct":false}]`
    : '';
  const correctEx = type === 'MCQ' ? '"A"' : type === 'TRUE_FALSE' ? '"True"' : '"model answer here"';

  const sys = 'You are an expert exam question generator. Return ONLY a valid JSON array. No markdown. No extra text.';
  const usr = `Generate ${count} unique ${difficulty} ${type} exam questions about "${topic}".
Each question must be different and test different concepts.
Return a JSON array with exactly ${count} objects:
[{"question_text":"?","question_type":"${type}","difficulty":"${difficulty}","correct_answer":${correctEx},"marks":${marks},"explanation":"why this is correct"${optionsEx}},...]`;

  try {
    const raw  = await groq(sys, usr, Math.min(count * 300 + 200, 4000), 0.8);
    const arr  = parseJSON(raw);
    const qs   = (Array.isArray(arr) ? arr : [arr]).map(q => ({
      ...q,
      marks:       Number(q.marks) || marks,
      question_id: Math.random().toString(36).substr(2, 9),
      options:     q.options?.slice(0,4).map(o => ({
        option_id:  Math.random().toString(36).substr(2, 9),
        text:       o.text || '',
        is_correct: Boolean(o.is_correct),
      })),
    }));
    if (onProgress) onProgress(count, count);
    return qs.slice(0, count);
  } catch (e) {
    throw new Error('Question generation failed: ' + e.message + '. Check GROQ key in backend .env');
  }
}

// ── Evaluate short answer ─────────────────────────────────────
export async function evaluateShortAnswer({ questionText, referenceAnswer, studentAnswer, maxMarks }) {
  try {
    const raw = await groq(
      'You are a strict examiner. Return ONLY valid JSON.',
      `Question: ${questionText}\nModel: ${referenceAnswer}\nStudent: ${studentAnswer}\nMax: ${maxMarks}\nReturn: {"score":<0-${maxMarks}>,"feedback":"2 sentences","percentage":<0-100>}`,
      200, 0.2
    );
    return parseJSON(raw);
  } catch { return { score: Math.floor(maxMarks*0.5), feedback: 'Auto-graded.', percentage: 50 }; }
}

// ── Evaluate descriptive ──────────────────────────────────────
export async function evaluateDescriptive({ questionText, referenceAnswer, studentAnswer, maxMarks }) {
  try {
    const raw = await groq(
      'You are an academic evaluator. Return ONLY valid JSON.',
      `Question: ${questionText}\nModel: ${referenceAnswer}\nStudent: ${studentAnswer}\nMax: ${maxMarks}\nReturn: {"score":<0-${maxMarks}>,"feedback":"3 sentences","percentage":<0-100>}`,
      300, 0.2
    );
    return parseJSON(raw);
  } catch { return { score: Math.floor(maxMarks*0.5), feedback: 'AI evaluation unavailable.', percentage: 50 }; }
}
